/** 並排行嘅綫之間嘅距離（格）= 綫闊：貼埋 */
export const MTR_MAP_GAP = 0.18;
/** 統一彎位半徑（圓弧）；並排綫一齊轉彎時外面嗰條喺座標度寫明加 G（同心） */
export const MTR_MAP_RADIUS = 0.7;
/** 支綫分岔站：畫雙圈（似轉車站，但冇綫色短棒）。主綫用站本身嗰點（上面），支綫由呢度寫嘅點（下面個圈）出發 */
export const MTR_MAP_DOUBLE: Readonly<Record<string, Pt>> = { TKO: [29.6, 15.76], SHS: [15.8, -0.42] };
/**
 * 兩個站之間一條細黑綫（唔同站名但可以轉車）：
 * 實綫 = 付費區內經行人通道轉乘（香港 ↔ 中環）；虛綫 = 要出閘經行人隧道轉乘（尖沙咀 ↔ 尖東，兩個站各自有閘）
 */
export interface MtrMapLink {
  a: string;
  b: string;
  dashed?: boolean;
}
